def simdiff(g,target,bg,neighbors,thresh=2, iterations=30):
 o=[row[:] for row in g]
 for it in range(iterations):
  n=[row[:] for row in o];changes=0
  for r in range(len(g)):
   for c in range(len(g[0])):
    if g[r][c]!=target:continue
    cnt=Counter()
    for dr,dc in neighbors:
     rr,cc=r+dr,c+dc
     if 0<=rr<len(g) and 0<=cc<len(g[0]) and o[rr][cc] not in (target,bg):cnt[o[rr][cc]]+=1
    if cnt:
     maxv=max(cnt.values());wins=[k for k,v in cnt.items() if v==maxv]
     if maxv>=thresh and len(wins)==1:
      n[r][c]=wins[0];changes+=1
  o=n
  if not changes:break
 return o,it
